cat > book.command.ts <<'E'
function authorName(id, ctx) {
  const [a] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${id}`);
  if (!a) {
    ctx.reject({ message: `author ${id} does not exist`, pointer: "/author_id" });
  }
  return a.name;
}

function check(published, authorId, ctx) {
  const name = authorName(authorId, ctx);
  if (published && (name === null || name === undefined || name === "")) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published" });
  }
}

export function create(input, ctx) {
  const published = input.published === true;
  check(published, input.author_id, ctx);
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}

export function update(input, ctx) {
  const [cur] = ctx.db.query(ctx.sql`SELECT author_id, published FROM book WHERE id = ${ctx.id}`);
  const authorId = "author_id" in input ? input.author_id : cur.author_id;
  const published = "published" in input ? input.published : cur.published;
  check(published, authorId, ctx);
  if ("title" in input) ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  if ("author_id" in input) ctx.db.exec(ctx.sql`UPDATE book SET author_id = ${input.author_id} WHERE id = ${ctx.id}`);
  if ("published" in input) ctx.db.exec(ctx.sql`UPDATE book SET published = ${input.published} WHERE id = ${ctx.id}`);
}

export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}
