    {"method": "GET", "path": "/business/export", "format": "csv", "query": "export.query.ts"}
  ],
  "properties": {
    "author": {"type": "string"},
    "published_books": {"type": "integer"}
  }
}
E
cat > export.query.ts <<'E'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`
    SELECT a.name AS author, count(b.id)::int AS published_books
    FROM author a
    LEFT JOIN book b ON b.author_id = a.id AND b.published
    WHERE a.name IS NOT NULL AND a.name <> ''
    GROUP BY a.id, a.name
    ORDER BY a.name, a.id`;
}
